using Payments;

namespace Payments.Tests;

/// <summary>
/// Fake implementation of <see cref="IPaymentProvider"/> for testing.
/// </summary>
internal sealed class FakePaymentProvider : IPaymentProvider
{
    public ChargeResult? NextChargeResult { get; set; }
    public RefundResult? NextRefundResult { get; set; }
    public Exception? ChargeException { get; set; }
    public Exception? RefundException { get; set; }

    public string? LastCardToken { get; private set; }
    public decimal LastAmount { get; private set; }
    public string? LastChargeId { get; private set; }

    public Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken cancellationToken = default)
    {
        LastCardToken = cardToken;
        LastAmount = amount;

        if (ChargeException is not null)
            throw ChargeException;

        return Task.FromResult(NextChargeResult ?? new ChargeResult("ch_default", true));
    }

    public Task<RefundResult> RefundAsync(string chargeId, CancellationToken cancellationToken = default)
    {
        LastChargeId = chargeId;

        if (RefundException is not null)
            throw RefundException;

        return Task.FromResult(NextRefundResult ?? new RefundResult("re_default", true));
    }
}

using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayChargeTests
{
    private readonly FakePaymentProvider _provider;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayChargeTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new PaymentGateway(_provider);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessResult()
    {
        _provider.NextChargeResult = new ChargeResult("ch_123", true);

        var result = await _gateway.ChargeAsync("tok_visa", 50.00m);

        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_PassesParametersToProvider()
    {
        await _gateway.ChargeAsync("tok_amex", 99.99m);

        Assert.AreEqual("tok_amex", _provider.LastCardToken);
        Assert.AreEqual(99.99m, _provider.LastAmount);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderDeclinesCharge_ReturnsFailureResult()
    {
        _provider.NextChargeResult = new ChargeResult("ch_declined", false);

        var result = await _gateway.ChargeAsync("tok_visa", 10.00m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual("ch_declined", result.ChargeId);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_NullOrWhiteSpaceToken_ThrowsArgumentException(string? token)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token!, 10.00m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", (decimal)amount));

        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ChargeException = new InvalidOperationException("Provider unavailable");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_visa", 25.00m));
    }

    [TestMethod]
    [DataRow(0.01)]
    [DataRow(1.00)]
    [DataRow(999999.99)]
    public async Task ChargeAsync_VariousPositiveAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_visa", (decimal)amount);

        Assert.IsTrue(result.Success);
    }
}

using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayRefundTests
{
    private readonly FakePaymentProvider _provider;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayRefundTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new PaymentGateway(_provider);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        _provider.NextRefundResult = new RefundResult("re_456", true);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.AreEqual("re_456", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_PassesIdToProvider()
    {
        await _gateway.RefundAsync("ch_abc");

        Assert.AreEqual("ch_abc", _provider.LastChargeId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderDeclinesRefund_ReturnsFailureResult()
    {
        _provider.NextRefundResult = new RefundResult("re_fail", false);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_NullOrWhiteSpaceChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.RefundException = new InvalidOperationException("Refund service down");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync("ch_123"));
    }
}

using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayWebhookTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayWebhookTests()
    {
        _gateway = new PaymentGateway(new FakePaymentProvider());
    }

    [TestMethod]
    [DataRow("charge.succeeded", "Charge confirmed")]
    [DataRow("charge.failed", "Charge failed")]
    [DataRow("refund.completed", "Refund completed")]
    public void ProcessWebhook_KnownEvent_ReturnsProcessedStatus(string eventType, string expectedMessage)
