using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayWebhookTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayWebhookTests()
    {
        _gateway = new PaymentGateway(new FakePaymentProvider());
    }

    [TestMethod]
    [DataRow("charge.succeeded", "Charge confirmed")]
    [DataRow("charge.failed", "Charge failed")]
    [DataRow("refund.completed", "Refund completed")]
    public void ProcessWebhook_KnownEvent_ReturnsProcessedStatus(string eventType, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, "{\"id\":\"evt_1\"}");

        Assert.AreEqual(WebhookStatus.Processed, result.Status);
        Assert.AreEqual(expectedMessage, result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_UnknownEvent_ReturnsIgnoredStatus()
    {
        var result = _gateway.ProcessWebhook("unknown.event", "{\"id\":\"evt_2\"}");

        Assert.AreEqual(WebhookStatus.Ignored, result.Status);
        Assert.Contains("Unknown event", result.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ProcessWebhook_NullOrWhiteSpaceEventType_ThrowsArgumentException(string? eventType)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, "payload"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ProcessWebhook_NullOrWhiteSpacePayload_ThrowsArgumentException(string? payload)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook("charge.succeeded", payload!));
    }
}

